public sealed class GameSingleton
{
    private static GameSingleton _instance;

    public static GameSingleton Instance
    {
        get
        {
            if (_instance == null)
                _instance = new GameSingleton();
            return _instance;
        }
    }

    private GameSingleton() { }
}

